import{_ as a}from"./chunks/verified-sharetribe-expert.DXKPC2U1.js";import{c as t,Q as r,j as o,m as n}from"./chunks/framework.BwfbE4MI.js";const b=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1779859611000}'),i={name:"faq.md"};function s(d,e,h,l,c,u){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="what-is-n8n" tabindex="-1">What is n8n? <a class="header-anchor" href="#what-is-n8n" aria-label="Permalink to &quot;What is n8n?&quot;">​</a></h2><p><a href="https://n8n.io" target="_blank" rel="noreferrer">n8n</a> is an open-source workflow automation tool - think Zapier or Make. You drag boxes onto a canvas, connect them with lines, and it runs.</p><h2 id="what-is-this-node" tabindex="-1">What is this node? <a class="header-anchor" href="#what-is-this-node" aria-label="Permalink to &quot;What is this node?&quot;">​</a></h2><p>A community node that adds Sharetribe as a service inside n8n. Once installed, n8n can listen for Sharetribe events (new transaction, new user, booking accepted, etc.) and run actions against your marketplace (approve users, update listings, transition transactions, etc.) without you writing code.</p><h2 id="what-can-i-do-with-it" tabindex="-1">What can I do with it? <a class="header-anchor" href="#what-can-i-do-with-it" aria-label="Permalink to &quot;What can I do with it?&quot;">​</a></h2><p>Anything you can do with the Sharetribe Integration API, automated. See the <a href="/n8n-nodes-sharetribe-docs/templates">workflow templates</a> for ready-made examples - admin email alerts, booking calendar invites, approving users only after a paid Stripe subscription, syncing new sign-ups to Mailchimp, and more.</p><h2 id="does-it-work-on-n8n-cloud-or-only-self-hosted" tabindex="-1">Does it work on n8n Cloud or only self-hosted? <a class="header-anchor" href="#does-it-work-on-n8n-cloud-or-only-self-hosted" aria-label="Permalink to &quot;Does it work on n8n Cloud or only self-hosted?&quot;">​</a></h2><p>Both. Community nodes are supported on n8n Cloud - see <a href="https://docs.n8n.io/integrations/community-nodes/installation/" target="_blank" rel="noreferrer">n8n&#39;s installation guide</a>.</p><h2 id="what-does-it-cost" tabindex="-1">What does it cost? <a class="header-anchor" href="#what-does-it-cost" aria-label="Permalink to &quot;What does it cost?&quot;">​</a></h2><p>The node is free and open source. You&#39;ll need a Sharetribe plan that includes Integration API access (Build, Pro, or Extend) and an n8n account (self-hosted or Cloud).</p><h2 id="is-it-official" tabindex="-1">Is it official? <a class="header-anchor" href="#is-it-official" aria-label="Permalink to &quot;Is it official?&quot;">​</a></h2><p>It&#39;s a community-built node, not first-party from Sharetribe or n8n. It&#39;s maintained by <a href="https://tribebuilder.dev" target="_blank" rel="noreferrer">TribeBuilder</a>, a verified Sharetribe Expert and verified n8n community node publisher.</p><a href="https://experts.sharetribe.com/l/greg-long-freelance-developer/6973f22c-9cdb-4b3a-b0bd-7aa5e3915fe0" target="_blank" rel="noreferrer"><img src="'+a+'" alt="Verified Sharetribe Expert" style="max-width:200px;"></a><h2 id="how-do-i-report-bugs-or-suggest-features" tabindex="-1">How do I report bugs or suggest features? <a class="header-anchor" href="#how-do-i-report-bugs-or-suggest-features" aria-label="Permalink to &quot;How do I report bugs or suggest features?&quot;">​</a></h2><p>Open an issue at <a href="https://github.com/tribebuilder/n8n-nodes-sharetribe/issues" target="_blank" rel="noreferrer">tribebuilder/n8n-nodes-sharetribe</a>.</p>',16)])])}const m=t(i,[["render",s]]);export{b as __pageData,m as default};
